insert into sim.dish (slug, doc) values (
  $sd$american-spiced-nuts$sd$,
  $sd${"title":"Rosemary Spiced Nuts","description":"Mixed nuts roasted with butter, rosemary, and cayenne, tossed while still hot so the seasoning sticks. Twelve servings, gone in twenty minutes.\n\nKeeps two weeks airtight, and re-crisps in a low oven for five minutes if it softens.","cuisine":"American","category":"Snack","difficulty":"easy","prep_minutes":10,"cook_minutes":15,"servings":12,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":500,"unit":"g","name":"mixed nuts","note":"unsalted — pecans, cashews, almonds","is_optional":false},{"quantity":2,"unit":"Tbsp","name":"butter","note":"melted","is_optional":false},{"quantity":2,"unit":"Tbsp","name":"rosemary","note":"chopped fine","is_optional":false},{"quantity":1,"unit":"Tbsp","name":"brown sugar","note":null,"is_optional":false},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false},{"quantity":0.5,"unit":"tsp","name":"cayenne","note":"adjust to taste","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Spread the mixed nuts on a tray and roast until they smell toasted and have taken a little colour.","duration_minutes":15,"temperature":"350°F","tip":"Shake the tray halfway. Nuts go from perfect to burnt in about ninety seconds."},{"text":"Combine the melted butter, rosemary, brown sugar, salt, and cayenne in a large bowl.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Tip the hot nuts straight into the bowl and toss until every one is coated.","duration_minutes":null,"temperature":null,"tip":"Hot is doing the work here — the rosemary fries slightly against the nuts and the sugar just melts."},{"text":"Spread back out to cool and crisp before serving.","duration_minutes":20,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["Holiday {title}","Maple {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- argentine-chimichurri.json
insert into sim.dish (slug, doc) values (
  $sd$argentine-chimichurri$sd$,
  $sd${"title":"Chimichurri","description":"Raw parsley, oregano, garlic, and vinegar loosened with oil. Chopped by hand, never blended — a food processor turns it into green paste.\n\nMakes about a cup. Keeps a week refrigerated, though the parsley darkens after day two.","cuisine":"Argentine","category":"Sauce","difficulty":"easy","prep_minutes":15,"cook_minutes":0,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":1,"unit":"cup","name":"flat-leaf parsley","note":"packed, chopped fine by hand","is_optional":false},{"quantity":2,"unit":"Tbsp","name":"dried oregano","note":null,"is_optional":false},{"quantity":6,"unit":"cloves","name":"garlic","note":"minced","is_optional":false},{"quantity":1,"unit":null,"name":"red chilli","note":"minced; or 1 tsp chilli flakes","is_optional":false},{"quantity":0.5,"unit":"cup","name":"olive oil","note":null,"is_optional":false},{"quantity":3,"unit":"Tbsp","name":"red wine vinegar","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"warm water","note":null,"is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Dissolve the salt in the warm water and add the dried oregano to rehydrate it.","duration_minutes":5,"temperature":null,"tip":"Dried oregano straight into oil stays woody. Water first."},{"text":"Chop the parsley, garlic, and red chilli finely by hand and combine them in a bowl.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Stir in the oregano mixture and the red wine vinegar, then pour in the olive oil and stir once — it should stay loose and separated, not emulsified.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Leave to sit before using.","duration_minutes":30,"temperature":null,"tip":"It tastes harsh for the first half hour and then settles."}]}],"weight":1.2,"variant_titles":["{title} Rojo","{title} for Steak"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- british-lemon-posset.json
insert into sim.dish (slug, doc) values (
  $sd$british-lemon-posset$sd$,
  $sd${"title":"Lemon Posset","description":"Three ingredients, one pan, and no setting agent — the acid in the lemon does all of it. Sets to something between a custard and a curd in four hours.\n\nThe ratio matters more than the technique. Too little lemon and it never sets; too much and it splits.","cuisine":"British","category":"Dessert","difficulty":"easy","prep_minutes":10,"cook_minutes":8,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":600,"unit":"ml","name":"heavy cream","note":null,"is_optional":false},{"quantity":150,"unit":"g","name":"sugar","note":null,"is_optional":false},{"quantity":3,"unit":null,"name":"lemons","note":"zest of two, juice of all three","is_optional":false},{"quantity":1,"unit":"handful","name":"raspberries","note":"to serve","is_optional":true}]}],"step_groups":[{"name":"","steps":[{"text":"Bring the heavy cream, sugar, and lemon zest to a boil, stirring until the sugar has dissolved.","duration_minutes":5,"temperature":null,"tip":"Use a bigger pan than seems necessary — cream climbs fast once it goes."},{"text":"Boil steadily for three minutes, watching it does not go over.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Take off the heat, stir in the lemon juice, and leave it to thicken slightly.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Strain out the zest and pour into four glasses.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Chill until set.","duration_minutes":240,"temperature":null,"tip":null},{"text":"Serve with raspberries.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.3,"variant_titles":["{title} with Shortbread","Blood Orange {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- chinese-ginger-congee.json
insert into sim.dish (slug, doc) values (
  $sd$chinese-ginger-congee$sd$,
  $sd${"title":"Ginger Congee","description":"Rice cooked far past the point most recipes stop, until the grains dissolve into something between soup and porridge. Plain on purpose — the toppings do the talking.\n\nFreezing the rinsed rice overnight breaks the grains and cuts the cooking time by about a third.","cuisine":"Chinese","category":"Breakfast","difficulty":"easy","prep_minutes":5,"cook_minutes":90,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":150,"unit":"g","name":"jasmine rice","note":"rinsed until the water runs clear","is_optional":false},{"quantity":2,"unit":"L","name":"chicken stock","note":"or water for a plainer bowl","is_optional":false},{"quantity":1,"unit":"large piece","name":"ginger","note":"half sliced, half julienned","is_optional":false},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false},{"quantity":2,"unit":null,"name":"spring onions","note":"sliced, to serve","is_optional":false},{"quantity":2,"unit":"Tbsp","name":"soy sauce","note":"to serve","is_optional":false},{"quantity":1,"unit":"tsp","name":"sesame oil","note":"to serve","is_optional":false},{"quantity":4,"unit":null,"name":"eggs","note":"soft boiled, to serve","is_optional":true}]}],"step_groups":[{"name":"","steps":[{"text":"Bring the jasmine rice, chicken stock, sliced ginger, and salt to a boil in a large pot.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Drop to the lowest possible heat and cook uncovered, stirring every fifteen minutes or so.","duration_minutes":80,"temperature":"low","tip":"Stir along the bottom each time — congee catches and scorches without warning."},{"text":"Stop when the grains have broken down and the congee coats the back of a spoon. Loosen with hot water if it has gone too far.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Serve topped with the julienned ginger, spring onions, soy sauce, sesame oil, and a soft boiled egg.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title} with Century Egg","Sick-Day {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- colombian-arepas.json
insert into sim.dish (slug, doc) values (
  $sd$colombian-arepas$sd$,
  $sd${"title":"Cheese Arepas","description":"Corn cakes made from precooked masarepa, griddled until they blister and split open with steam. Four ingredients, and the dough tells you when it is right.\n\nMasarepa is not the same as masa harina and not the same as cornmeal — neither substitute works.","cuisine":"Colombian","category":"Side","difficulty":"easy","prep_minutes":15,"cook_minutes":20,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":250,"unit":"g","name":"masarepa","note":"precooked white corn flour","is_optional":false},{"quantity":400,"unit":"ml","name":"warm water","note":null,"is_optional":false},{"quantity":150,"unit":"g","name":"queso fresco","note":"crumbled; mozzarella works","is_optional":false},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"butter","note":"for the griddle","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Stir the salt into the warm water, then rain in the masarepa, mixing with your hand.","duration_minutes":null,"temperature":null,"tip":"Flour into water, not the other way round — it hydrates evenly and you get no dry pockets."},{"text":"Knead in the queso fresco and let the dough rest so the corn finishes absorbing.","duration_minutes":10,"temperature":null,"tip":"The dough should feel like soft clay. If it cracks at the edge when you flatten it, wet your hands and knead again."},{"text":"Shape into eight discs about a centimetre thick, smoothing the edges between wet palms.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Griddle in butter over a medium heat until a crust forms and they sound hollow, turning once.","duration_minutes":20,"temperature":"medium","tip":"A finished arepa puffs slightly and hisses. Do not press it down."}]}],"weight":1.3,"variant_titles":["{title} with Butter","Stuffed {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- egyptian-koshari.json
insert into sim.dish (slug, doc) values (
  $sd$egyptian-koshari$sd$,
  $sd${"title":"Koshari","description":"Rice, lentils, and pasta layered under a sharp tomato sauce, cumin vinegar, and a heap of fried onions. Egypt's national dish and the best argument for carbohydrate on carbohydrate.\n\nEvery component can be made ahead. Assemble only at the table — the fried onions go soft within minutes of meeting the sauce.","cuisine":"Egyptian","category":"Main","difficulty":"medium","prep_minutes":25,"cook_minutes":60,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Base","ingredients":[{"quantity":200,"unit":"g","name":"brown lentils","note":"rinsed","is_optional":false},{"quantity":200,"unit":"g","name":"rice","note":null,"is_optional":false},{"quantity":150,"unit":"g","name":"small pasta","note":"elbows or ditalini","is_optional":false},{"quantity":400,"unit":"g","name":"chickpeas","note":"cooked and drained","is_optional":false}]},{"name":"Tomato sauce","ingredients":[{"quantity":700,"unit":"g","name":"tomato passata","note":null,"is_optional":false},{"quantity":4,"unit":"cloves","name":"garlic","note":"minced","is_optional":false},{"quantity":2,"unit":"Tbsp","name":"white vinegar","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"cumin","note":"ground","is_optional":false},{"quantity":0.5,"unit":"tsp","name":"chilli flakes","note":null,"is_optional":false}]},{"name":"Crispy onions","ingredients":[{"quantity":3,"unit":null,"name":"onions","note":"sliced very thin","is_optional":false},{"quantity":250,"unit":"ml","name":"neutral oil","note":"for frying","is_optional":false}]}],"step_groups":[{"name":"Crispy onions","steps":[{"text":"Fry the sliced onions in the neutral oil over a steady medium heat until deep brown and crisp, then drain on paper.","duration_minutes":25,"temperature":null,"tip":"They go from brown to burnt fast at the end. Pull them a shade early — they darken on the paper."},{"text":"Keep a few spoonfuls of the onion oil back for the lentils.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"Base","steps":[{"text":"Simmer the brown lentils in plenty of water until tender but still holding shape, then drain.","duration_minutes":20,"temperature":null,"tip":null},{"text":"Cook the rice in the reserved onion oil and water until done, and boil the pasta separately.","duration_minutes":18,"temperature":null,"tip":null}]},{"name":"Sauce and assembly","steps":[{"text":"Fry the garlic briefly, add the tomato passata, cumin, chilli flakes, and white vinegar, and simmer until thickened.","duration_minutes":15,"temperature":null,"tip":null},{"text":"Layer rice, lentils, pasta, and chickpeas in a wide dish.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Pour the hot sauce over and finish with a generous pile of crispy onions.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.2,"variant_titles":["Street-Style {title}","{title} for a Crowd"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- ethiopian-misir-wot.json
insert into sim.dish (slug, doc) values (
  $sd$ethiopian-misir-wot$sd$,
  $sd${"title":"Misir Wot","description":"Red lentils cooked down with berbere and a large quantity of onion, which is dry-cooked first without any fat at all. Thick enough to eat with bread rather than a spoon.\n\nBerbere varies enormously in heat between brands. Start with half and build.","cuisine":"Ethiopian","category":"Main","difficulty":"easy","prep_minutes":15,"cook_minutes":55,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":null,"name":"red onions","note":"diced very fine","is_optional":false},{"quantity":250,"unit":"g","name":"red lentils","note":"rinsed","is_optional":false},{"quantity":3,"unit":"Tbsp","name":"berbere","note":null,"is_optional":false},{"quantity":3,"unit":"Tbsp","name":"niter kibbeh","note":"spiced clarified butter; or plain ghee","is_optional":false},{"quantity":4,"unit":"cloves","name":"garlic","note":"minced","is_optional":false},{"quantity":1,"unit":"Tbsp","name":"ginger","note":"grated","is_optional":false},{"quantity":2,"unit":"Tbsp","name":"tomato paste","note":null,"is_optional":false},{"quantity":1,"unit":"L","name":"water","note":"hot","is_optional":false},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Cook the red onions in a dry pan, with no oil, stirring often until they collapse and release their moisture.","duration_minutes":15,"temperature":"medium-low","tip":"This sounds wrong and is the defining step. The onions steam in their own liquid and go sweet without frying."},{"text":"Add the niter kibbeh, garlic, and ginger and cook until fragrant.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Stir in the berbere and tomato paste and cook them out so the spice loses its raw edge.","duration_minutes":4,"temperature":null,"tip":null},{"text":"Add the red lentils and the hot water, and simmer, stirring now and then.","duration_minutes":30,"temperature":null,"tip":null},{"text":"Season with the salt and cook until it is thick enough to hold the mark of a spoon.","duration_minutes":5,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["{title} with Injera","Mild {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- filipino-garlic-fried-rice.json
insert into sim.dish (slug, doc) values (
  $sd$filipino-garlic-fried-rice$sd$,
  $sd${"title":"Garlic Fried Rice","description":"Sinangag. Day-old rice fried in garlic oil with a heavy hand of fried garlic folded back through at the end. A side dish that quietly outshines what it is served with.\n\nFreshly cooked rice will not work — it steams and clumps. Cold rice from yesterday is the requirement, not a shortcut.","cuisine":"Filipino","category":"Side","difficulty":"easy","prep_minutes":10,"cook_minutes":15,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":4,"unit":"cups","name":"cooked rice","note":"cold, from the day before, broken up by hand","is_optional":false},{"quantity":12,"unit":"cloves","name":"garlic","note":"minced","is_optional":false},{"quantity":4,"unit":"Tbsp","name":"neutral oil","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false},{"quantity":2,"unit":null,"name":"spring onions","note":"sliced, to finish","is_optional":false},{"quantity":4,"unit":null,"name":"eggs","note":"fried, to serve","is_optional":true}]}],"step_groups":[{"name":"","steps":[{"text":"Fry the minced garlic in the neutral oil over a medium-low heat until pale gold, then lift half of it out onto paper.","duration_minutes":5,"temperature":"medium-low","tip":"Pull it while it is lighter than you want — it keeps browning on the paper. Burnt garlic is bitter and unfixable."},{"text":"Turn the heat up, add the cold cooked rice to the garlic oil left in the pan, and press it into an even layer.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Leave it alone so the underside crisps, then turn and repeat.","duration_minutes":8,"temperature":null,"tip":"Constant stirring gives you warm rice. Stillness gives you texture."},{"text":"Season with the salt, fold through the reserved crisp garlic and the spring onions, and serve with a fried egg.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.4,"variant_titles":["{title} with Longganisa","Everyday {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- french-coq-au-vin.json
insert into sim.dish (slug, doc) values (
  $sd$french-coq-au-vin$sd$,
  $sd${"title":"Coq au Vin","description":"Chicken braised in red wine with bacon, mushrooms, and small onions. The garnish is cooked separately and added at the end so it does not turn grey in the pot.\n\nA whole bottle goes in. Use one you would drink, but not one you would miss.","cuisine":"French","category":"Main","difficulty":"hard","prep_minutes":40,"cook_minutes":90,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Braise","ingredients":[{"quantity":1.6,"unit":"kg","name":"chicken","note":"jointed into eight pieces","is_optional":false},{"quantity":750,"unit":"ml","name":"red wine","note":"a full bottle","is_optional":false},{"quantity":150,"unit":"g","name":"bacon lardons","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"all-purpose flour","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"tomato paste","note":null,"is_optional":false},{"quantity":3,"unit":"cloves","name":"garlic","note":"crushed","is_optional":false},{"quantity":1,"unit":null,"name":"bouquet garni","note":"thyme, bay, parsley stalks tied together","is_optional":false},{"quantity":300,"unit":"ml","name":"chicken stock","note":null,"is_optional":false}]},{"name":"Garnish","ingredients":[{"quantity":250,"unit":"g","name":"button mushrooms","note":"left whole if small","is_optional":false},{"quantity":250,"unit":"g","name":"pearl onions","note":"peeled","is_optional":false},{"quantity":30,"unit":"g","name":"butter","note":null,"is_optional":false},{"quantity":1,"unit":"handful","name":"parsley","note":"chopped, to finish","is_optional":false}]}],"step_groups":[{"name":"Braise","steps":[{"text":"Render the bacon lardons in a heavy pot until crisp, then lift them out.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Brown the chicken hard in the bacon fat, in batches, and set aside.","duration_minutes":15,"temperature":null,"tip":"Crowding the pan steams the skin. Batches are slower and not optional."},{"text":"Stir the flour and tomato paste into the fat with the crushed garlic and cook out the raw taste.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Pour in the red wine, scraping the base, and reduce by about a third.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Return the chicken and bacon, add the chicken stock and bouquet garni, and simmer covered.","duration_minutes":60,"temperature":"low","tip":null}]},{"name":"Garnish and finish","steps":[{"text":"Brown the pearl onions and button mushrooms separately in the butter until well coloured.","duration_minutes":12,"temperature":null,"tip":"Cooking these in the braise turns them the colour of the wine. Separate is the whole point."},{"text":"Add the garnish to the pot for the last few minutes, discard the bouquet garni, and check the seasoning.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Finish with chopped parsley.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.8,"variant_titles":["{title} Blanc","Sunday {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- georgian-khachapuri.json
insert into sim.dish (slug, doc) values (
  $sd$georgian-khachapuri$sd$,
  $sd${"title":"Adjaruli Khachapuri","description":"A boat of enriched dough filled with salty cheese, finished with an egg yolk and butter stirred through at the table while everything is still molten.\n\nYou tear the pointed ends off and use them to stir the yolk into the cheese. That is the correct way to eat it and it is not optional.","cuisine":"Georgian","category":"Main","difficulty":"medium","prep_minutes":30,"cook_minutes":18,"servings":2,"attribution":null,"ingredient_groups":[{"name":"Dough","ingredients":[{"quantity":300,"unit":"g","name":"bread flour","note":null,"is_optional":false},{"quantity":175,"unit":"ml","name":"milk","note":"warm","is_optional":false},{"quantity":7,"unit":"g","name":"instant yeast","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"sugar","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false}]},{"name":"Filling","ingredients":[{"quantity":200,"unit":"g","name":"sulguni","note":"or half mozzarella, half feta","is_optional":false},{"quantity":100,"unit":"g","name":"feta","note":"crumbled","is_optional":false},{"quantity":2,"unit":null,"name":"egg yolks","note":null,"is_optional":false},{"quantity":40,"unit":"g","name":"butter","note":"cubed","is_optional":false}]}],"step_groups":[{"name":"Dough","steps":[{"text":"Mix the bread flour, instant yeast, sugar, and salt, then work in the warm milk and olive oil and knead until smooth.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Prove until doubled.","duration_minutes":90,"temperature":null,"tip":null}]},{"name":"Shaping and baking","steps":[{"text":"Divide in two, roll each piece into an oval, and roll the long sides inward to make thick ropes.","duration_minutes":null,"temperature":null,"tip":"Pinch the two ends together hard. A boat that opens in the oven loses all its cheese."},{"text":"Mix the sulguni and feta and heap it into each boat.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Bake until the crust is deep gold and the cheese is bubbling.","duration_minutes":15,"temperature":"450°F","tip":null},{"text":"Pull the tray out, drop an egg yolk and some butter into each pool of cheese, and return briefly so the yolk warms without setting.","duration_minutes":2,"temperature":null,"tip":"The yolk should still be liquid when it reaches the table."}]}],"weight":0.9,"variant_titles":["{title} for One","Imeruli {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- german-dutch-baby.json
insert into sim.dish (slug, doc) values (
  $sd$german-dutch-baby$sd$,
  $sd${"title":"Dutch Baby Pancake","description":"A single pancake that climbs the sides of a hot skillet in the oven and collapses the moment it comes out. Five minutes of work, and the batter does the rest.\n\nRoom-temperature eggs and milk are the difference between a dramatic rise and a flat disc.","cuisine":"German","category":"Breakfast","difficulty":"easy","prep_minutes":10,"cook_minutes":20,"servings":2,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":null,"name":"eggs","note":"room temperature","is_optional":false},{"quantity":0.5,"unit":"cup","name":"milk","note":"room temperature","is_optional":false},{"quantity":0.5,"unit":"cup","name":"all-purpose flour","note":null,"is_optional":false},{"quantity":1,"unit":"Tbsp","name":"sugar","note":null,"is_optional":false},{"quantity":0.25,"unit":"tsp","name":"salt","note":null,"is_optional":false},{"quantity":3,"unit":"Tbsp","name":"butter","note":null,"is_optional":false},{"quantity":1,"unit":null,"name":"lemon","note":"to serve","is_optional":false},{"quantity":2,"unit":"Tbsp","name":"powdered sugar","note":"to serve","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Put a cast iron skillet in the oven and heat it thoroughly.","duration_minutes":15,"temperature":"425°F","tip":"The pan must be properly hot before the batter hits it. This is the whole trick."},{"text":"Blend the eggs, milk, flour, sugar, and salt until completely smooth and slightly frothy.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Let the batter stand while the pan finishes heating.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Drop the butter into the hot skillet, swirl it up the sides as it melts, then pour the batter straight in.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Bake without opening the door until puffed and deeply browned at the edges.","duration_minutes":20,"temperature":"425°F","tip":null},{"text":"Serve straight from the pan with a squeeze of lemon and a dusting of powdered sugar.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.2,"variant_titles":["Savoury {title}","{title} with Berries"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- greek-lamb-souvlaki.json
insert into sim.dish (slug, doc) values (
  $sd$greek-lamb-souvlaki$sd$,
  $sd${"title":"Lamb Souvlaki with Tzatziki","description":"Lamb shoulder marinated overnight in lemon, oregano, and garlic, then grilled hard and fast. The tzatziki is drained twice so it stays thick instead of sliding off.","cuisine":"Greek","category":"Main","difficulty":"medium","prep_minutes":30,"cook_minutes":12,"servings":4,"attribution":null,"ingredient_groups":[{"name":"Lamb and marinade","ingredients":[{"quantity":800,"unit":"g","name":"lamb shoulder","note":"cut into 3cm cubes","is_optional":false},{"quantity":3,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false},{"quantity":1,"unit":null,"name":"lemon","note":"zest and juice","is_optional":false},{"quantity":1,"unit":"Tbsp","name":"dried oregano","note":null,"is_optional":false},{"quantity":4,"unit":"cloves","name":"garlic","note":"crushed","is_optional":false},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false}]},{"name":"Tzatziki","ingredients":[{"quantity":300,"unit":"g","name":"Greek yogurt","note":"full fat","is_optional":false},{"quantity":1,"unit":null,"name":"cucumber","note":"coarsely grated","is_optional":false},{"quantity":1,"unit":"clove","name":"garlic","note":"grated fine","is_optional":false},{"quantity":1,"unit":"Tbsp","name":"red wine vinegar","note":null,"is_optional":false},{"quantity":1,"unit":"Tbsp","name":"dill","note":"chopped","is_optional":false}]}],"step_groups":[{"name":"The day before","steps":[{"text":"Toss the lamb shoulder with the olive oil, lemon zest and juice, oregano, crushed garlic, and salt.","duration_minutes":null,"temperature":null,"tip":"Salt in the marinade is doing double duty — it seasons and it keeps the meat juicy."},{"text":"Cover and refrigerate.","duration_minutes":720,"temperature":null,"tip":null}]},{"name":"Tzatziki","steps":[{"text":"Salt the grated cucumber and leave it in a sieve, then squeeze it dry in a cloth.","duration_minutes":20,"temperature":null,"tip":"Squeeze harder than feels reasonable. Watery tzatziki starts here."},{"text":"Stir the cucumber into the Greek yogurt with the grated garlic, red wine vinegar, and dill.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"Grilling","steps":[{"text":"Thread the lamb onto skewers, leaving a little space between the pieces so they colour rather than steam.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Grill over the highest heat you have, turning every couple of minutes.","duration_minutes":12,"temperature":"high","tip":null},{"text":"Rest the skewers before serving with the tzatziki.","duration_minutes":5,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["{title}, Family Style"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- indian-chana-masala.json
insert into sim.dish (slug, doc) values (
  $sd$indian-chana-masala$sd$,
  $sd${"title":"Chana Masala","description":"Chickpeas in a dark onion-tomato masala finished with amchur for sourness rather than lemon. Entirely pantry-based and better on the second day.\n\nTinned chickpeas are fine. If cooking dried, save the cooking liquid — it thickens the gravy better than water.","cuisine":"Indian","category":"Main","difficulty":"easy","prep_minutes":15,"cook_minutes":40,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":800,"unit":"g","name":"chickpeas","note":"cooked, drained; two tins","is_optional":false},{"quantity":2,"unit":null,"name":"onions","note":"diced fine","is_optional":false},{"quantity":3,"unit":null,"name":"tomatoes","note":"chopped","is_optional":false},{"quantity":1,"unit":"Tbsp","name":"ginger","note":"grated","is_optional":false},{"quantity":4,"unit":"cloves","name":"garlic","note":"minced","is_optional":false},{"quantity":2,"unit":"tsp","name":"cumin","note":"ground","is_optional":false},{"quantity":2,"unit":"tsp","name":"coriander","note":"ground","is_optional":false},{"quantity":1,"unit":"tsp","name":"garam masala","note":null,"is_optional":false},{"quantity":0.5,"unit":"tsp","name":"turmeric","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"amchur","note":"dried mango powder; or the juice of half a lemon","is_optional":false},{"quantity":3,"unit":"Tbsp","name":"neutral oil","note":null,"is_optional":false},{"quantity":1,"unit":"handful","name":"cilantro","note":"chopped, to finish","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Fry the onions in the neutral oil until well past golden — properly brown at the edges.","duration_minutes":15,"temperature":"medium","tip":"Most of the colour of the finished dish comes from here. Stopping at soft and translucent gives a pale, thin curry."},{"text":"Add the ginger and garlic and cook until the raw smell goes.","duration_minutes":2,"temperature":null,"tip":null},{"text":"Add the cumin, coriander, and turmeric and stir for thirty seconds before the tomatoes go in.","duration_minutes":1,"temperature":null,"tip":null},{"text":"Add the tomatoes and cook down until the oil separates out at the edges.","duration_minutes":12,"temperature":null,"tip":"Oil pooling around the masala is the signal it is ready. It is not a timing question."},{"text":"Stir in the chickpeas with a splash of water and simmer so they take on the gravy.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Crush a few chickpeas against the side of the pan to thicken, then finish with garam masala, amchur, and cilantro.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.6,"variant_titles":["Weeknight {title}","{title} with Spinach","Pantry {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- indonesian-beef-rendang.json
insert into sim.dish (slug, doc) values (
  $sd$indonesian-beef-rendang$sd$,
  $sd${"title":"Beef Rendang","description":"Beef simmered in coconut milk and spice paste until the liquid goes, then fried in the oil that separates out. The last twenty minutes are where it stops being a curry.\n\nStop early and you have a wet rendang, which is a real dish but a different one. Dry rendang keeps for days unrefrigerated, which is what it was for.","cuisine":"Indonesian","category":"Main","difficulty":"hard","prep_minutes":30,"cook_minutes":210,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Spice paste","ingredients":[{"quantity":10,"unit":null,"name":"shallots","note":"peeled","is_optional":false},{"quantity":6,"unit":"cloves","name":"garlic","note":null,"is_optional":false},{"quantity":8,"unit":null,"name":"dried red chillies","note":"soaked in hot water","is_optional":false},{"quantity":4,"unit":"cm","name":"galangal","note":"sliced","is_optional":false},{"quantity":3,"unit":"cm","name":"ginger","note":"sliced","is_optional":false},{"quantity":2,"unit":"tsp","name":"coriander","note":"ground","is_optional":false}]},{"name":"Braise","ingredients":[{"quantity":1.2,"unit":"kg","name":"beef chuck","note":"cut into large cubes","is_optional":false},{"quantity":800,"unit":"ml","name":"coconut milk","note":"full fat","is_optional":false},{"quantity":3,"unit":"stalks","name":"lemongrass","note":"bruised","is_optional":false},{"quantity":6,"unit":null,"name":"kaffir lime leaves","note":null,"is_optional":false},{"quantity":2,"unit":null,"name":"turmeric leaves","note":"tied in a knot","is_optional":true},{"quantity":1,"unit":"Tbsp","name":"palm sugar","note":null,"is_optional":false},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Blend the shallots, garlic, soaked dried red chillies, galangal, ginger, and coriander into a smooth paste with a splash of water.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fry the paste in a wide heavy pot until it darkens and smells sweet rather than raw.","duration_minutes":12,"temperature":null,"tip":"A wide pot, not a deep one. The whole method depends on evaporation."},{"text":"Add the beef chuck and turn it through the paste until sealed.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Pour in the coconut milk and add the lemongrass, kaffir lime leaves, turmeric leaves, palm sugar, and salt.","duration_minutes":null,"temperature":null,"tip":"Do not cover the pot at any point."},{"text":"Simmer uncovered, stirring occasionally, until the sauce has reduced to a thick gravy.","duration_minutes":150,"temperature":"low","tip":null},{"text":"Keep going. The oil will split out and the gravy will turn dark brown — now stir constantly so the beef fries in it rather than catching.","duration_minutes":25,"temperature":null,"tip":"This is the actual cooking. The colour goes from tan to near-black and the smell changes completely."},{"text":"Serve once the beef is coated in dark paste and there is no liquid left in the pot.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.8,"variant_titles":["Dry {title}","{title}, Wet Style"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- israeli-shakshuka.json
insert into sim.dish (slug, doc) values (
  $sd$israeli-shakshuka$sd$,
  $sd${"title":"Shakshuka","description":"Eggs poached in a thick pepper and tomato sauce, spiced with cumin and caraway. One pan, and the sauce keeps for days without the eggs.","cuisine":"Israeli","category":"Breakfast","difficulty":"easy","prep_minutes":15,"cook_minutes":35,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false},{"quantity":1,"unit":null,"name":"onion","note":"diced","is_optional":false},{"quantity":2,"unit":null,"name":"red bell peppers","note":"sliced","is_optional":false},{"quantity":4,"unit":"cloves","name":"garlic","note":"sliced","is_optional":false},{"quantity":1,"unit":"tsp","name":"cumin","note":"ground","is_optional":false},{"quantity":0.5,"unit":"tsp","name":"caraway seed","note":"crushed","is_optional":false},{"quantity":1,"unit":"tsp","name":"sweet paprika","note":null,"is_optional":false},{"quantity":800,"unit":"g","name":"tinned tomatoes","note":"crushed by hand","is_optional":false},{"quantity":6,"unit":null,"name":"eggs","note":null,"is_optional":false},{"quantity":100,"unit":"g","name":"feta","note":"crumbled","is_optional":false},{"quantity":1,"unit":"handful","name":"parsley","note":"chopped, to finish","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Cook the onion and red bell peppers in the olive oil until genuinely soft and beginning to catch.","duration_minutes":15,"temperature":"medium-low","tip":"This is where the sweetness comes from. Ten minutes is not enough."},{"text":"Add the garlic, cumin, caraway seed, and paprika and stir until fragrant.","duration_minutes":2,"temperature":null,"tip":null},{"text":"Add the tinned tomatoes, season, and simmer until the sauce is thick enough to hold a channel when you drag a spoon through it.","duration_minutes":15,"temperature":null,"tip":null},{"text":"Make six wells and crack an egg into each.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Cover and cook until the whites are set and the yolks are still loose.","duration_minutes":6,"temperature":null,"tip":"Pull it a minute early — the pan carries on cooking at the table."},{"text":"Scatter over the feta and parsley.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.6,"variant_titles":["Green {title}","{title} for Two","Sunday {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- italian-tiramisu.json
insert into sim.dish (slug, doc) values (
  $sd$italian-tiramisu$sd$,
  $sd${"title":"Tiramisu","description":"Mascarpone and whipped egg over coffee-soaked savoiardi, set overnight in the fridge. No cream, no gelatine, and no baking — the structure comes entirely from the eggs.\n\nThe yolks are cooked over a bain-marie rather than left raw, which also makes the mixture more stable.","cuisine":"Italian","category":"Dessert","difficulty":"medium","prep_minutes":35,"cook_minutes":8,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":4,"unit":null,"name":"eggs","note":"separated","is_optional":false},{"quantity":100,"unit":"g","name":"sugar","note":null,"is_optional":false},{"quantity":500,"unit":"g","name":"mascarpone","note":"cold","is_optional":false},{"quantity":300,"unit":"ml","name":"espresso","note":"strong, cooled","is_optional":false},{"quantity":3,"unit":"Tbsp","name":"marsala","note":null,"is_optional":true},{"quantity":300,"unit":"g","name":"savoiardi","note":"hard ladyfingers, not soft sponge","is_optional":false},{"quantity":3,"unit":"Tbsp","name":"cocoa powder","note":"to finish","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Whisk the egg yolks with the sugar over a pan of barely simmering water until pale, thick, and hot to the touch.","duration_minutes":8,"temperature":"bain-marie","tip":"Keep the bowl clear of the water and keep whisking, or you make sweet scrambled egg."},{"text":"Cool the yolk mixture, then beat in the mascarpone a spoonful at a time until smooth.","duration_minutes":null,"temperature":null,"tip":"Cold mascarpone into warm yolks will split. Let the yolks come down first."},{"text":"Whip the egg whites to soft peaks and fold them through in three additions.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Combine the espresso and marsala in a shallow dish. Dip each savoiardi for a second per side — no longer.","duration_minutes":null,"temperature":null,"tip":"They should still be firm in the middle when they go down. They keep absorbing all night."},{"text":"Layer soaked savoiardi and cream twice, finishing with cream, and smooth the top.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Cover and refrigerate.","duration_minutes":720,"temperature":null,"tip":null},{"text":"Dust heavily with cocoa powder just before serving.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.5,"variant_titles":["{title} for a Party","Coffee-Free {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- jamaican-jerk-chicken.json
insert into sim.dish (slug, doc) values (
  $sd$jamaican-jerk-chicken$sd$,
  $sd${"title":"Jerk Chicken","description":"Chicken marinated overnight in scotch bonnet, allspice, and thyme, then cooked slowly over indirect heat. The pimento wood is the traditional smoke; a covered grill gets close.\n\nAllspice — pimento — is doing more work here than the chilli. Buy it whole and grind it.","cuisine":"Jamaican","category":"Main","difficulty":"medium","prep_minutes":25,"cook_minutes":75,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Jerk marinade","ingredients":[{"quantity":4,"unit":null,"name":"scotch bonnet peppers","note":"seeded for less heat","is_optional":false},{"quantity":6,"unit":null,"name":"spring onions","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"allspice berries","note":"freshly ground","is_optional":false},{"quantity":2,"unit":"Tbsp","name":"thyme","note":"leaves picked","is_optional":false},{"quantity":4,"unit":"cloves","name":"garlic","note":null,"is_optional":false},{"quantity":3,"unit":"cm","name":"ginger","note":null,"is_optional":false},{"quantity":3,"unit":"Tbsp","name":"soy sauce","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"brown sugar","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"lime juice","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"nutmeg","note":"grated","is_optional":false},{"quantity":1,"unit":"tsp","name":"cinnamon","note":"ground","is_optional":false}]},{"name":"Chicken","ingredients":[{"quantity":1.8,"unit":"kg","name":"chicken thighs and drumsticks","note":"bone in, skin on, slashed to the bone","is_optional":false}]}],"step_groups":[{"name":"The day before","steps":[{"text":"Blend the scotch bonnet peppers, spring onions, allspice berries, thyme, garlic, ginger, soy sauce, brown sugar, lime juice, nutmeg, and cinnamon into a coarse marinade.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Work it into the slashed chicken thighs and drumsticks, getting into every cut.","duration_minutes":null,"temperature":null,"tip":"Wear gloves. Scotch bonnet oil stays on your hands for hours."},{"text":"Cover and refrigerate.","duration_minutes":720,"temperature":null,"tip":null}]},{"name":"Cooking","steps":[{"text":"Set the grill up for indirect heat — coals banked to one side, chicken on the other — and cook with the lid on.","duration_minutes":60,"temperature":"medium-low","tip":"Direct heat burns the sugar in the marinade long before the thigh is cooked through."},{"text":"Move the pieces over the coals for the last stretch to char the skin, turning often.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Rest, then chop through the bone into pieces to serve.","duration_minutes":10,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["Oven {title}","{title}, Mild"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- japanese-oyakodon.json
insert into sim.dish (slug, doc) values (
  $sd$japanese-oyakodon$sd$,
  $sd${"title":"Oyakodon","description":"Chicken and egg over rice, cooked in a shallow pan in about eight minutes. The egg goes in twice and never fully sets — that softness is the whole dish.","cuisine":"Japanese","category":"Main","difficulty":"easy","prep_minutes":10,"cook_minutes":10,"servings":2,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":250,"unit":"g","name":"chicken thighs","note":"boneless, cut into bite-sized pieces","is_optional":false},{"quantity":1,"unit":null,"name":"onion","note":"sliced thin","is_optional":false},{"quantity":4,"unit":null,"name":"eggs","note":"beaten loosely, streaks left in","is_optional":false},{"quantity":150,"unit":"ml","name":"dashi","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"soy sauce","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"mirin","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"sugar","note":null,"is_optional":false},{"quantity":2,"unit":"bowls","name":"steamed rice","note":"hot","is_optional":false},{"quantity":2,"unit":null,"name":"spring onions","note":"sliced, to finish","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Bring the dashi, soy sauce, mirin, and sugar to a simmer in a small shallow pan.","duration_minutes":2,"temperature":null,"tip":null},{"text":"Add the onion and cook until translucent.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Lay in the chicken in a single layer and simmer until just cooked through.","duration_minutes":4,"temperature":null,"tip":"Do not stir it about. The pieces should stay where you put them."},{"text":"Pour two-thirds of the beaten eggs over in a spiral and cover the pan.","duration_minutes":1,"temperature":null,"tip":null},{"text":"Add the remaining egg, cover again, and pull the pan off the heat while the top is still visibly loose.","duration_minutes":null,"temperature":null,"tip":"Residual heat finishes it. Set egg here means you have gone too far."},{"text":"Slide over hot steamed rice and scatter with spring onions.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.5,"variant_titles":["10-Minute {title}","{title} for One"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- korean-braised-short-ribs.json
insert into sim.dish (slug, doc) values (
  $sd$korean-braised-short-ribs$sd$,
  $sd${"title":"Korean Braised Short Ribs","description":"Galbi jjim — short ribs braised until the meat gives up and slides off the bone, in a sauce built on grated pear rather than extra sugar. A holiday dish that rewards a slow afternoon.\n\nBetter the next day. Cool the braise whole, lift the set fat off the top, and reheat gently.","cuisine":"Korean","category":"Main","difficulty":"hard","prep_minutes":30,"cook_minutes":135,"servings":6,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":1.5,"unit":"kg","name":"beef short ribs","note":"cut into 2-inch lengths","is_optional":false},{"quantity":0.5,"unit":"cup","name":"soy sauce","note":null,"is_optional":false},{"quantity":3,"unit":"Tbsp","name":"brown sugar","note":null,"is_optional":false},{"quantity":1,"unit":null,"name":"Asian pear","note":"peeled and grated; the enzyme is what tenderises","is_optional":false},{"quantity":8,"unit":"cloves","name":"garlic","note":"smashed","is_optional":false},{"quantity":1,"unit":"Tbsp","name":"ginger","note":"grated","is_optional":false},{"quantity":2,"unit":null,"name":"carrots","note":"cut into large chunks","is_optional":false},{"quantity":300,"unit":"g","name":"daikon radish","note":"cut into large chunks","is_optional":false},{"quantity":100,"unit":"g","name":"shiitake mushrooms","note":"halved","is_optional":false},{"quantity":1,"unit":"Tbsp","name":"sesame oil","note":null,"is_optional":false},{"quantity":3,"unit":null,"name":"spring onions","note":"sliced, to finish","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Soak the short ribs in cold water, changing it once, to draw out the blood.","duration_minutes":60,"temperature":null,"tip":"Skipping this is the difference between a clear braise and a muddy one."},{"text":"Parboil the ribs in fresh water, then drain and rinse each piece.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Blend the pear, garlic, and ginger with the soy sauce and brown sugar into a smooth braising liquid.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Return the ribs to the pot, pour over the liquid, and simmer covered on the lowest heat.","duration_minutes":90,"temperature":"low","tip":"The meat should be pulling back from the bone before anything else goes in."},{"text":"Add the carrots, daikon, and shiitake and cook uncovered so the sauce reduces and glazes.","duration_minutes":25,"temperature":null,"tip":null},{"text":"Turn off the heat, stir through the sesame oil, and scatter with spring onions.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.2,"variant_titles":["Sunday {title}","{title} with Daikon"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- lebanese-fattoush.json
insert into sim.dish (slug, doc) values (
  $sd$lebanese-fattoush$sd$,
  $sd${"title":"Fattoush","description":"A bread salad built to use up flatbread that has gone stale. Sumac and pomegranate molasses do the work; the pita has to stay crisp until it reaches the table.\n\nDress it at the table, not in the kitchen. Fattoush has a working life of about four minutes.","cuisine":"Lebanese","category":"Salad","difficulty":"easy","prep_minutes":20,"cook_minutes":0,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":2,"unit":null,"name":"pita breads","note":"stale, torn into pieces and toasted crisp","is_optional":false},{"quantity":4,"unit":null,"name":"tomatoes","note":"cut into wedges","is_optional":false},{"quantity":2,"unit":null,"name":"Persian cucumbers","note":"roughly chopped","is_optional":false},{"quantity":4,"unit":null,"name":"radishes","note":"sliced","is_optional":false},{"quantity":4,"unit":null,"name":"spring onions","note":"sliced","is_optional":false},{"quantity":1,"unit":"cup","name":"flat-leaf parsley","note":"leaves picked","is_optional":false},{"quantity":0.5,"unit":"cup","name":"mint","note":"leaves picked","is_optional":false},{"quantity":2,"unit":"tsp","name":"sumac","note":null,"is_optional":false},{"quantity":1,"unit":"Tbsp","name":"pomegranate molasses","note":null,"is_optional":false},{"quantity":4,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false},{"quantity":1,"unit":null,"name":"lemon","note":"juiced","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Whisk the olive oil, lemon juice, pomegranate molasses, and half the sumac with a good pinch of salt.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Combine the tomatoes, Persian cucumbers, radishes, spring onions, parsley, and mint in a wide bowl.","duration_minutes":null,"temperature":null,"tip":"Cut everything to roughly the same size so no one component dominates a forkful."},{"text":"Add the toasted pita breads and pour over the dressing.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Toss once, dust with the remaining sumac, and take it straight to the table.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["{title} with Purslane"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- malaysian-curry-laksa.json
insert into sim.dish (slug, doc) values (
  $sd$malaysian-curry-laksa$sd$,
  $sd${"title":"Curry Laksa","description":"Noodles in a coconut curry broth built on a fried spice paste, with tofu puffs that soak up more soup than seems physically reasonable.","cuisine":"Malaysian","category":"Soup","difficulty":"medium","prep_minutes":30,"cook_minutes":35,"servings":4,"attribution":null,"ingredient_groups":[{"name":"Laksa paste","ingredients":[{"quantity":8,"unit":null,"name":"dried red chillies","note":"soaked","is_optional":false},{"quantity":6,"unit":null,"name":"shallots","note":null,"is_optional":false},{"quantity":4,"unit":"cloves","name":"garlic","note":null,"is_optional":false},{"quantity":2,"unit":"stalks","name":"lemongrass","note":"white part only","is_optional":false},{"quantity":2,"unit":"cm","name":"turmeric","note":"fresh, or 1 tsp ground","is_optional":false},{"quantity":1,"unit":"Tbsp","name":"belacan","note":"shrimp paste, toasted","is_optional":false},{"quantity":30,"unit":"g","name":"candlenuts","note":"or macadamias","is_optional":false}]},{"name":"Soup","ingredients":[{"quantity":400,"unit":"ml","name":"coconut milk","note":null,"is_optional":false},{"quantity":800,"unit":"ml","name":"chicken stock","note":null,"is_optional":false},{"quantity":300,"unit":"g","name":"rice noodles","note":null,"is_optional":false},{"quantity":200,"unit":"g","name":"prawns","note":"peeled","is_optional":false},{"quantity":8,"unit":null,"name":"tofu puffs","note":"halved","is_optional":false},{"quantity":100,"unit":"g","name":"bean sprouts","note":null,"is_optional":false},{"quantity":1,"unit":"Tbsp","name":"fish sauce","note":null,"is_optional":false},{"quantity":1,"unit":"handful","name":"Vietnamese mint","note":"to serve","is_optional":false},{"quantity":1,"unit":null,"name":"lime","note":"cut into wedges, to serve","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Blend the soaked dried red chillies, shallots, garlic, lemongrass, turmeric, belacan, and candlenuts into a fine paste.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fry the paste in oil over a medium heat until it darkens and the oil separates.","duration_minutes":15,"temperature":null,"tip":"Fifteen minutes is not an exaggeration. Underfried paste tastes raw and grainy in the finished soup."},{"text":"Add the chicken stock and bring to a simmer, then stir in the coconut milk and fish sauce.","duration_minutes":10,"temperature":null,"tip":"Keep it below a rolling boil once the coconut milk is in, or it splits."},{"text":"Add the tofu puffs and let them drink the broth.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Poach the prawns in the soup until just opaque.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Cook the rice noodles separately, divide between bowls, and ladle the soup over.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Top with bean sprouts and Vietnamese mint, and serve with lime wedges.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title}, Vegetarian","Weeknight {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- mexican-carnitas-tacos.json
insert into sim.dish (slug, doc) values (
  $sd$mexican-carnitas-tacos$sd$,
  $sd${"title":"Carnitas Tacos","description":"Pork shoulder cooked slowly in its own fat with orange and bay, then crisped hard under a broiler. Soft, rich, and shatteringly crisp in the same forkful.\n\nThe crisping step is not optional. Braised pork alone is not carnitas.","cuisine":"Mexican","category":"Main","difficulty":"medium","prep_minutes":20,"cook_minutes":195,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":1.8,"unit":"kg","name":"pork shoulder","note":"cut into large cubes, fat left on","is_optional":false},{"quantity":1,"unit":null,"name":"orange","note":"halved","is_optional":false},{"quantity":1,"unit":null,"name":"white onion","note":"quartered","is_optional":false},{"quantity":6,"unit":"cloves","name":"garlic","note":null,"is_optional":false},{"quantity":2,"unit":null,"name":"bay leaves","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"cumin seed","note":null,"is_optional":false},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false},{"quantity":16,"unit":null,"name":"corn tortillas","note":"to serve","is_optional":false},{"quantity":1,"unit":"bunch","name":"cilantro","note":"to serve","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Put the pork shoulder in a heavy pot with the onion, garlic, bay leaves, cumin seed, and salt. Squeeze the orange over and drop both halves in.","duration_minutes":null,"temperature":null,"tip":"The peel goes in too — the oils in it are half the point."},{"text":"Add water to come halfway up the meat and bring to a bare simmer.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Cook uncovered on the lowest heat until the water has gone and the pork is frying in its own rendered fat.","duration_minutes":170,"temperature":"low","tip":null},{"text":"Lift the meat out, discard the bay, orange, onion, and garlic, and shred it coarsely with two forks.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Spread the shredded pork on a tray, spoon over some of the rendered fat, and broil until the edges are dark and crisp.","duration_minutes":8,"temperature":"broil","tip":"Do not stir it while it crisps, or you get steam instead of crust."},{"text":"Warm the corn tortillas, fill, and finish with cilantro.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.4,"variant_titles":["{title} with Pickled Onion","Slow {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- moroccan-chicken-tagine.json
insert into sim.dish (slug, doc) values (
  $sd$moroccan-chicken-tagine$sd$,
  $sd${"title":"Chicken Tagine with Olives and Preserved Lemon","description":"Chicken cooked down with saffron, ginger, and a whole preserved lemon until the sauce is thick enough to coat a spoon. Salty, sour, and barely sweet.","cuisine":"Moroccan","category":"Main","difficulty":"medium","prep_minutes":25,"cook_minutes":60,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Chermoula","ingredients":[{"quantity":4,"unit":"cloves","name":"garlic","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"ginger","note":"ground","is_optional":false},{"quantity":1,"unit":"tsp","name":"sweet paprika","note":null,"is_optional":false},{"quantity":0.5,"unit":"tsp","name":"turmeric","note":null,"is_optional":false},{"quantity":1,"unit":"pinch","name":"saffron","note":"crumbled into a little warm water","is_optional":false},{"quantity":3,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false}]},{"name":"Tagine","ingredients":[{"quantity":1.4,"unit":"kg","name":"chicken thighs","note":"bone in, skin on","is_optional":false},{"quantity":2,"unit":null,"name":"onions","note":"sliced thin","is_optional":false},{"quantity":1,"unit":null,"name":"preserved lemon","note":"flesh discarded, rind sliced","is_optional":false},{"quantity":150,"unit":"g","name":"green olives","note":"cracked, rinsed","is_optional":false},{"quantity":300,"unit":"ml","name":"chicken stock","note":null,"is_optional":false},{"quantity":1,"unit":"bunch","name":"cilantro","note":"chopped, to finish","is_optional":false}]}],"step_groups":[{"name":"Chermoula","steps":[{"text":"Pound the garlic to a paste with a little salt, then work in the ginger, paprika, turmeric, bloomed saffron, and olive oil.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Rub the chermoula into the chicken thighs and leave them to take on colour.","duration_minutes":30,"temperature":null,"tip":"An hour is better, overnight better still."}]},{"name":"Tagine","steps":[{"text":"Brown the chicken skin-side down in a heavy pot, then lift it out.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Soften the onions in the same fat until collapsing and sweet.","duration_minutes":12,"temperature":"medium-low","tip":null},{"text":"Return the chicken, pour in the chicken stock, cover, and simmer.","duration_minutes":30,"temperature":null,"tip":null},{"text":"Add the preserved lemon rind and green olives and cook uncovered so the sauce reduces and thickens.","duration_minutes":10,"temperature":null,"tip":"Taste before adding any salt — the lemon and olives already brought plenty."},{"text":"Finish with the chopped cilantro.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title} for a Crowd"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- peruvian-ceviche.json
insert into sim.dish (slug, doc) values (
  $sd$peruvian-ceviche$sd$,
  $sd${"title":"Peruvian Ceviche","description":"White fish cured in lime juice for minutes, not hours, with chilli, red onion, and the cloudy leftover marinade poured back over. Nothing is cooked with heat.\n\nBuy the fish the same day and keep everything cold. This is the one recipe where ingredient quality is the entire technique.","cuisine":"Peruvian","category":"Appetizer","difficulty":"easy","prep_minutes":25,"cook_minutes":0,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":500,"unit":"g","name":"sea bass","note":"skinless, boneless, cut into 2cm cubes; any firm white fish works","is_optional":false},{"quantity":10,"unit":null,"name":"limes","note":"juiced, about 250ml","is_optional":false},{"quantity":1,"unit":null,"name":"red onion","note":"sliced paper thin","is_optional":false},{"quantity":1,"unit":null,"name":"aji amarillo","note":"seeded and sliced; substitute a mild yellow chilli","is_optional":false},{"quantity":1,"unit":"clove","name":"garlic","note":"grated fine","is_optional":false},{"quantity":1,"unit":"small piece","name":"ginger","note":"grated fine","is_optional":false},{"quantity":1,"unit":"bunch","name":"cilantro","note":"chopped","is_optional":false},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false},{"quantity":1,"unit":null,"name":"sweet potato","note":"boiled and sliced, to serve","is_optional":true}]}],"step_groups":[{"name":"","steps":[{"text":"Soak the sliced red onion in ice water to take the harsh edge off, then drain it well.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Whisk the lime juice with the grated garlic, ginger, and salt to make the leche de tigre.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Toss the sea bass with the salt and let it sit briefly before the acid goes anywhere near it.","duration_minutes":2,"temperature":null,"tip":"Salting first firms the surface so the fish cures evenly instead of going chalky outside and raw inside."},{"text":"Pour the leche de tigre over the fish and stir once.","duration_minutes":3,"temperature":null,"tip":"Three minutes. The cubes should turn opaque at the edge and stay translucent at the centre."},{"text":"Fold through the drained onion, aji amarillo, and cilantro, and serve immediately with sliced sweet potato.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.9,"variant_titles":["{title} with Mango"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- polish-pierogi-ruskie.json
insert into sim.dish (slug, doc) values (
  $sd$polish-pierogi-ruskie$sd$,
  $sd${"title":"Pierogi Ruskie","description":"Dumplings filled with potato and twarog, boiled and then fried in butter with onions. The dough is worked warm and rested, which is what keeps it from tearing.\n\nFreeze them raw on a tray before bagging, and boil from frozen. They do not survive being stacked wet.","cuisine":"Polish","category":"Main","difficulty":"hard","prep_minutes":70,"cook_minutes":25,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Dough","ingredients":[{"quantity":500,"unit":"g","name":"all-purpose flour","note":null,"is_optional":false},{"quantity":250,"unit":"ml","name":"water","note":"warm","is_optional":false},{"quantity":2,"unit":"Tbsp","name":"butter","note":"melted","is_optional":false},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false}]},{"name":"Filling","ingredients":[{"quantity":600,"unit":"g","name":"potatoes","note":"boiled and riced","is_optional":false},{"quantity":250,"unit":"g","name":"twarog","note":"farmer's cheese; substitute dry ricotta","is_optional":false},{"quantity":2,"unit":null,"name":"onions","note":"one for the filling, one to serve","is_optional":false},{"quantity":60,"unit":"g","name":"butter","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"white pepper","note":null,"is_optional":false}]}],"step_groups":[{"name":"Dough","steps":[{"text":"Mix the flour and salt with the warm water and melted butter, then knead until smooth and elastic.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Cover and rest the dough.","duration_minutes":30,"temperature":null,"tip":"Unrested dough springs back while you are trying to fill it and the seals fail."}]},{"name":"Filling","steps":[{"text":"Fry one diced onion in half the butter until deep golden.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Mash the fried onion into the riced potatoes and twarog with the white pepper and plenty of salt, and let it cool completely.","duration_minutes":null,"temperature":null,"tip":"Taste it and over-season slightly — the dough around it is unsalted."}]},{"name":"Shaping and cooking","steps":[{"text":"Roll the dough thin and cut rounds, keeping the offcuts covered as you go.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Place a spoonful of filling on each round, fold, and pinch the edge firmly all the way along.","duration_minutes":null,"temperature":null,"tip":"Wet fingers make the seal worse, not better. Dry, firm pressure holds."},{"text":"Boil in well-salted water in batches until they float, then give them another minute.","duration_minutes":12,"temperature":null,"tip":null},{"text":"Fry the remaining sliced onion in the rest of the butter and toss the drained pierogi through it.","duration_minutes":8,"temperature":null,"tip":null}]}],"weight":0.7,"variant_titles":["Grandmother's {title}","{title} with Bacon"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- portuguese-pastel-de-nata.json
insert into sim.dish (slug, doc) values (
  $sd$portuguese-pastel-de-nata$sd$,
  $sd${"title":"Pastéis de Nata","description":"Custard tarts baked in the hottest oven you have, so the tops blister black while the centre stays loose. The pastry is rolled into a log and cut, not lined.\n\nMakes 12. Domestic ovens rarely reach the 300°C these want; go as hot as yours goes and put the tray on the floor of the oven.","cuisine":"Portuguese","category":"Dessert","difficulty":"hard","prep_minutes":45,"cook_minutes":15,"servings":12,"attribution":null,"ingredient_groups":[{"name":"Custard","ingredients":[{"quantity":250,"unit":"g","name":"sugar","note":null,"is_optional":false},{"quantity":120,"unit":"ml","name":"water","note":null,"is_optional":false},{"quantity":1,"unit":"stick","name":"cinnamon","note":null,"is_optional":false},{"quantity":1,"unit":null,"name":"lemon","note":"peel in strips, no pith","is_optional":false},{"quantity":500,"unit":"ml","name":"milk","note":null,"is_optional":false},{"quantity":40,"unit":"g","name":"all-purpose flour","note":null,"is_optional":false},{"quantity":6,"unit":null,"name":"egg yolks","note":null,"is_optional":false}]},{"name":"Pastry","ingredients":[{"quantity":400,"unit":"g","name":"puff pastry","note":"all butter, at room temperature","is_optional":false}]}],"step_groups":[{"name":"Custard","steps":[{"text":"Boil the sugar and water with the cinnamon stick and lemon peel to a thin syrup, then set it aside to infuse.","duration_minutes":5,"temperature":"220°F","tip":null},{"text":"Whisk the flour into a little of the cold milk to a smooth slurry, then stir in the rest of the milk and cook until thickened.","duration_minutes":6,"temperature":null,"tip":"Lumps here cannot be fixed later. Slurry first, always."},{"text":"Strain the warm syrup into the hot milk mixture in a steady stream, whisking.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Let it cool below blood heat, then whisk in the egg yolks and strain the custard.","duration_minutes":15,"temperature":null,"tip":"Yolks into anything hotter than this scramble instantly."}]},{"name":"Shaping and baking","steps":[{"text":"Roll the puff pastry into a tight log, cut it into 12 discs, and press each cut-side-down into a muffin tin, thumbing it up the sides.","duration_minutes":null,"temperature":null,"tip":"Cut side down is what gives the layered spiral on the base."},{"text":"Chill the cases while the oven heats as high as it will go.","duration_minutes":20,"temperature":null,"tip":null},{"text":"Fill each case three-quarters full and bake until the tops are blistered and blackened in patches.","duration_minutes":15,"temperature":"as hot as the oven goes","tip":"The black spots are correct. Pale tarts are underbaked."},{"text":"Cool briefly and eat warm, dusted with cinnamon.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.7,"variant_titles":["{title}, Shortcut Pastry"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- russian-blini.json
insert into sim.dish (slug, doc) values (
  $sd$russian-blini$sd$,
  $sd${"title":"Buckwheat Blini","description":"Yeast-raised buckwheat pancakes, left to ferment overnight so they come out sour and lacy rather than sweet. Served with sour cream and whatever is salty.\n\nThe overnight rise is the flavour. A one-hour version works and tastes like a plain pancake.","cuisine":"Russian","category":"Breakfast","difficulty":"medium","prep_minutes":20,"cook_minutes":25,"servings":6,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":150,"unit":"g","name":"buckwheat flour","note":null,"is_optional":false},{"quantity":150,"unit":"g","name":"all-purpose flour","note":null,"is_optional":false},{"quantity":500,"unit":"ml","name":"milk","note":"warm","is_optional":false},{"quantity":7,"unit":"g","name":"instant yeast","note":null,"is_optional":false},{"quantity":2,"unit":null,"name":"eggs","note":"separated","is_optional":false},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false},{"quantity":30,"unit":"g","name":"butter","note":"melted, plus more for the pan","is_optional":false},{"quantity":200,"unit":"g","name":"sour cream","note":"to serve","is_optional":false}]}],"step_groups":[{"name":"The night before","steps":[{"text":"Whisk the buckwheat flour, all-purpose flour, instant yeast, and warm milk into a loose batter.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Cover and leave at room temperature to ferment.","duration_minutes":600,"temperature":null,"tip":"It should smell distinctly sour in the morning and be covered in bubbles."}]},{"name":"Morning","steps":[{"text":"Beat in the egg yolks, salt, and melted butter.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Whip the egg whites to soft peaks and fold them through.","duration_minutes":null,"temperature":null,"tip":"Fold, do not stir. The air is what makes them lacy."},{"text":"Cook spoonfuls in a buttered pan over a medium heat until the surface is covered in holes, then turn.","duration_minutes":25,"temperature":"medium","tip":null},{"text":"Serve hot with sour cream.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.9,"variant_titles":["{title} with Smoked Fish","Quick {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- south-african-malva-pudding.json
insert into sim.dish (slug, doc) values (
  $sd$south-african-malva-pudding$sd$,
  $sd${"title":"Malva Pudding","description":"A sticky apricot jam sponge that has hot cream sauce poured over it straight from the oven and drinks all of it. Served warm, never cold.\n\nThe sauce must go on while both the pudding and the sauce are hot. Cold sauce sits on top instead of soaking in.","cuisine":"South African","category":"Dessert","difficulty":"medium","prep_minutes":20,"cook_minutes":45,"servings":8,"attribution":null,"ingredient_groups":[{"name":"Pudding","ingredients":[{"quantity":200,"unit":"g","name":"sugar","note":null,"is_optional":false},{"quantity":2,"unit":null,"name":"eggs","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"apricot jam","note":null,"is_optional":false},{"quantity":220,"unit":"g","name":"all-purpose flour","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"baking soda","note":null,"is_optional":false},{"quantity":200,"unit":"ml","name":"milk","note":null,"is_optional":false},{"quantity":1,"unit":"Tbsp","name":"white vinegar","note":null,"is_optional":false},{"quantity":30,"unit":"g","name":"butter","note":"melted","is_optional":false}]},{"name":"Sauce","ingredients":[{"quantity":200,"unit":"ml","name":"heavy cream","note":null,"is_optional":false},{"quantity":100,"unit":"g","name":"butter","note":null,"is_optional":false},{"quantity":100,"unit":"g","name":"sugar","note":null,"is_optional":false},{"quantity":100,"unit":"ml","name":"hot water","note":null,"is_optional":false}]}],"step_groups":[{"name":"Pudding","steps":[{"text":"Beat the sugar and eggs until thick and pale, then beat in the apricot jam and melted butter.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Stir the baking soda into the milk with the white vinegar — it will froth — and fold it into the batter with the flour.","duration_minutes":null,"temperature":null,"tip":"Work quickly once the soda and vinegar meet. The lift starts immediately."},{"text":"Pour into a buttered dish and bake until risen and deep brown.","duration_minutes":45,"temperature":"350°F","tip":null}]},{"name":"Sauce","steps":[{"text":"Warm the heavy cream, butter, sugar, and hot water together until the sugar dissolves.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Prick the hot pudding all over and pour the hot sauce over it in stages, letting each addition disappear.","duration_minutes":null,"temperature":null,"tip":"It will look like far too much liquid. It is not."},{"text":"Stand before serving so the sponge finishes absorbing.","duration_minutes":10,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title} for a Crowd"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- spanish-seafood-paella.json
insert into sim.dish (slug, doc) values (
  $sd$spanish-seafood-paella$sd$,
  $sd${"title":"Seafood Paella","description":"Rice cooked flat in a wide pan and never stirred, so the bottom layer caramelises into socarrat. The seafood goes in late and stays whole.\n\nUse the widest pan you own. Depth is the enemy — the rice should sit no more than two grains deep.","cuisine":"Spanish","category":"Main","difficulty":"hard","prep_minutes":25,"cook_minutes":40,"servings":6,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":400,"unit":"g","name":"bomba rice","note":"or another short-grain paella rice","is_optional":false},{"quantity":1.2,"unit":"L","name":"fish stock","note":"hot","is_optional":false},{"quantity":1,"unit":"pinch","name":"saffron","note":"bloomed in a little hot stock","is_optional":false},{"quantity":300,"unit":"g","name":"prawns","note":"shell on","is_optional":false},{"quantity":300,"unit":"g","name":"mussels","note":"scrubbed and debearded","is_optional":false},{"quantity":200,"unit":"g","name":"squid","note":"cut into rings","is_optional":false},{"quantity":1,"unit":null,"name":"onion","note":"diced fine","is_optional":false},{"quantity":3,"unit":"cloves","name":"garlic","note":"minced","is_optional":false},{"quantity":2,"unit":null,"name":"tomatoes","note":"grated, skins discarded","is_optional":false},{"quantity":1,"unit":"tsp","name":"sweet paprika","note":null,"is_optional":false},{"quantity":4,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false},{"quantity":1,"unit":null,"name":"lemon","note":"cut into wedges, to serve","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Sear the prawns and squid briefly in the olive oil and set them aside — they will finish later.","duration_minutes":3,"temperature":null,"tip":null},{"text":"In the same pan, cook the onion and garlic down, then add the grated tomatoes and sweet paprika and reduce to a dark sofrito.","duration_minutes":12,"temperature":null,"tip":"The sofrito should be jammy and almost dry. This is where most of the flavour lives."},{"text":"Stir in the bomba rice and coat it in the sofrito.","duration_minutes":2,"temperature":null,"tip":null},{"text":"Pour in the hot fish stock and the bloomed saffron, spread the rice level, and do not stir again.","duration_minutes":null,"temperature":null,"tip":"From this point a spoon is forbidden. Stirring releases starch and you get risotto."},{"text":"Cook at a strong simmer, turning the pan for even heat.","duration_minutes":12,"temperature":"medium-high","tip":null},{"text":"Push the mussels into the rice hinge-down, return the prawns and squid to the top, and cook until the liquid has gone.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Raise the heat for the last minute to build the socarrat — listen for it crackling.","duration_minutes":2,"temperature":"high","tip":null},{"text":"Rest off the heat under a cloth, then serve with lemon wedges.","duration_minutes":5,"temperature":null,"tip":null}]}],"weight":0.9,"variant_titles":["{title} for Six","Mixed {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- thai-green-curry-chicken.json
insert into sim.dish (slug, doc) values (
  $sd$thai-green-curry-chicken$sd$,
  $sd${"title":"Thai Green Curry with Chicken","description":"Gaeng keow wan gai. The trick is cracking the coconut cream with the paste before anything else joins — that split, oily stage is where the flavour comes from.","cuisine":"Thai","category":"Main","difficulty":"medium","prep_minutes":20,"cook_minutes":25,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":"Tbsp","name":"green curry paste","note":null,"is_optional":false},{"quantity":400,"unit":"ml","name":"coconut milk","note":"full fat; do not shake the tin","is_optional":false},{"quantity":500,"unit":"g","name":"chicken thighs","note":"boneless, sliced","is_optional":false},{"quantity":150,"unit":"g","name":"Thai eggplant","note":"quartered; or 1 regular eggplant, cubed","is_optional":false},{"quantity":2,"unit":"Tbsp","name":"fish sauce","note":null,"is_optional":false},{"quantity":1,"unit":"tsp","name":"palm sugar","note":null,"is_optional":false},{"quantity":4,"unit":null,"name":"kaffir lime leaves","note":"torn","is_optional":false},{"quantity":1,"unit":"handful","name":"Thai basil","note":null,"is_optional":false},{"quantity":1,"unit":null,"name":"red chilli","note":"sliced, to finish","is_optional":true}]}],"step_groups":[{"name":"","steps":[{"text":"Spoon the thick cream from the top of the coconut milk tin into a hot pan and fry the green curry paste in it until the fat splits out and the mixture darkens.","duration_minutes":5,"temperature":null,"tip":"You are looking for visible oil pooling at the edges. Rushing this leaves the curry tasting raw."},{"text":"Add the chicken and turn it through the paste until it is coated and sealed.","duration_minutes":4,"temperature":null,"tip":null},{"text":"Pour in the rest of the coconut milk with the kaffir lime leaves and bring to a bare simmer.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Add the Thai eggplant and simmer until tender but not collapsing.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Season with fish sauce and palm sugar, tasting as you go — it should land salty, sweet, and hot in that order.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Take off the heat and stir through the Thai basil and sliced red chilli.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.3,"variant_titles":["Weeknight {title}","{title}, Extra Hot"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- turkish-mint-lemonade.json
insert into sim.dish (slug, doc) values (
  $sd$turkish-mint-lemonade$sd$,
  $sd${"title":"Mint Lemonade","description":"Whole lemons blitzed with mint and ice — peel included, which is where the perfume is. Strained once so it stays sharp rather than bitter.\n\nUse unwaxed lemons. If you can only get waxed ones, peel them and add a strip of zest back instead.","cuisine":"Turkish","category":"Drink","difficulty":"easy","prep_minutes":10,"cook_minutes":0,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":null,"name":"lemons","note":"unwaxed, quartered, seeds removed","is_optional":false},{"quantity":1,"unit":"cup","name":"mint","note":"leaves picked","is_optional":false},{"quantity":0.5,"unit":"cup","name":"sugar","note":"adjust to the fruit","is_optional":false},{"quantity":750,"unit":"ml","name":"cold water","note":null,"is_optional":false},{"quantity":2,"unit":"cups","name":"ice","note":null,"is_optional":false},{"quantity":1,"unit":"pinch","name":"salt","note":null,"is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Remove every seed from the quartered lemons.","duration_minutes":null,"temperature":null,"tip":"One missed seed makes the whole jug bitter. This is the only fiddly part."},{"text":"Blitz the lemons with the sugar, salt, mint, ice, and half the cold water in short bursts.","duration_minutes":1,"temperature":null,"tip":"Short bursts only. Long blending pulls bitterness out of the pith."},{"text":"Strain through a coarse sieve, pressing lightly, and top up with the remaining cold water.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Taste and adjust with more sugar or lemon, then serve over ice.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["Frozen {title}","{title} with Cucumber"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- ukrainian-borscht.json
insert into sim.dish (slug, doc) values (
  $sd$ukrainian-borscht$sd$,
  $sd${"title":"Ukrainian Borscht","description":"Beet soup with a beef broth base, soured with vinegar at the end so the colour stays red rather than turning brown. Makes a large pot and improves for three days.\n\nThe vinegar is not for flavour alone — acid is what fixes the pigment. Add it too late and the pot has already gone dull.","cuisine":"Ukrainian","category":"Soup","difficulty":"medium","prep_minutes":30,"cook_minutes":120,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":800,"unit":"g","name":"beef short rib","note":"bone in","is_optional":false},{"quantity":3,"unit":"L","name":"water","note":null,"is_optional":false},{"quantity":3,"unit":null,"name":"beets","note":"peeled and coarsely grated","is_optional":false},{"quantity":2,"unit":null,"name":"carrots","note":"grated","is_optional":false},{"quantity":1,"unit":null,"name":"onion","note":"diced","is_optional":false},{"quantity":300,"unit":"g","name":"white cabbage","note":"shredded","is_optional":false},{"quantity":3,"unit":null,"name":"potatoes","note":"cubed","is_optional":false},{"quantity":2,"unit":"Tbsp","name":"tomato paste","note":null,"is_optional":false},{"quantity":2,"unit":"Tbsp","name":"red wine vinegar","note":null,"is_optional":false},{"quantity":3,"unit":"cloves","name":"garlic","note":"crushed","is_optional":false},{"quantity":1,"unit":"bunch","name":"dill","note":"chopped, to finish","is_optional":false},{"quantity":200,"unit":"g","name":"sour cream","note":"to serve","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Simmer the beef short rib in the water, skimming the foam off for the first few minutes, until the meat is tender.","duration_minutes":90,"temperature":null,"tip":"Skim properly at the start and the broth stays clear for the rest of the cook."},{"text":"Lift out the beef, pull the meat from the bone, and return it to the pot.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fry the onion and carrots until soft, then add the beets, tomato paste, and one tablespoon of the red wine vinegar and cook down.","duration_minutes":15,"temperature":null,"tip":"Souring the beets in the pan is the insurance policy for the colour."},{"text":"Add the potatoes to the broth and cook until nearly done.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Stir in the beet mixture and the white cabbage and simmer until the cabbage is just tender.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Off the heat, stir in the crushed garlic and the remaining vinegar, then season hard.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Serve with dill and a spoonful of sour cream in each bowl.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title}, Meat Free","Grandmother's {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- vietnamese-caramel-pork.json
insert into sim.dish (slug, doc) values (
  $sd$vietnamese-caramel-pork$sd$,
  $sd${"title":"Vietnamese Caramel Pork","description":"Thit kho. Pork belly simmered in a caramel taken right to the edge of burnt, with fish sauce and coconut water. Dark, salty, and sweet in that order.\n\nThe caramel should smell almost scorched before the liquid goes in. Pale caramel makes a sweet, flat dish.","cuisine":"Vietnamese","category":"Main","difficulty":"easy","prep_minutes":15,"cook_minutes":75,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":700,"unit":"g","name":"pork belly","note":"skin on, cut into 3cm pieces","is_optional":false},{"quantity":4,"unit":"Tbsp","name":"sugar","note":null,"is_optional":false},{"quantity":3,"unit":"Tbsp","name":"fish sauce","note":null,"is_optional":false},{"quantity":400,"unit":"ml","name":"coconut water","note":null,"is_optional":false},{"quantity":4,"unit":"cloves","name":"garlic","note":"sliced","is_optional":false},{"quantity":2,"unit":null,"name":"shallots","note":"sliced","is_optional":false},{"quantity":4,"unit":null,"name":"eggs","note":"hard boiled and peeled","is_optional":false},{"quantity":1,"unit":"tsp","name":"black pepper","note":"coarsely cracked","is_optional":false}]}],"step_groups":[{"name":"","steps":[{"text":"Melt the sugar in a dry heavy pot and let it go to a deep mahogany caramel without stirring.","duration_minutes":6,"temperature":null,"tip":"Swirl the pan rather than stirring. Take it one shade darker than looks wise."},{"text":"Add the garlic and shallots to the caramel — it will seize and spit — and stir until fragrant.","duration_minutes":1,"temperature":null,"tip":null},{"text":"Add the pork belly and turn it until every piece is coated and starting to colour.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Pour in the coconut water and fish sauce, add the cracked black pepper, and bring to a simmer.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Cook covered on a low heat until the pork is tender.","duration_minutes":50,"temperature":"low","tip":null},{"text":"Add the hard boiled eggs and cook uncovered so the sauce reduces to a glaze and the eggs stain brown.","duration_minutes":12,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title} with Eggs"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

